mapper.select:
SELECT ASSTYPE, ASSID, ASSNAME, ASSDES, ASSLEVEL, ASSSJBM FROM ${dbSource}.TBL_ASS_INFO WHERE 1=1
and AYEAR = ${bookYear}
order by ASSTYPE,ASSID asc

SELECT B.ASSID as assId,B.ASSNAME as assName,B.ASSTYPE as assType,NVL(B.QCMD,'0') AS qcmd,NVL(B.QCMC,'0') AS qcmc, NVL(B.BQMD,'0') AS bqmd,NVL(B.BQMC,'0') AS bqmc,NVL(B.QMMD,'0') AS qmmd, NVL(B.QMMC,'0') AS qmmc,B.QCDC as qcdc,B.QMDC as qmdc ,B.AID AS aid FROM ${dbSource}.TBL_ASS_BAL B WHERE 1=1
and B.AYEAR = ${bookYear}
ORDER BY B.ASSID,B.ASSNAME

SELECT COUNT(0) FROM ${dbSource}.TBL_ASS_BAL B
WHERE 1=1

    and B.AYEAR = ${bookYear}

SELECT ASSTYPE FROM ${dbSource}.TBL_ASS_INFO 
WHERE ASSTYPE != 'null' AND ASSTYPE != 'NULL' AND ASSTYPE IS NOT NULL AND AYEAR = ${bookYear} 
GROUP BY ASSTYPE ORDER BY ASSTYPE ASC
